const f = msg.floorStock;
if (!f) return null;
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const byDevice = new Map();
for (const doc of rows) {
    const s = doc?.lineStats || {};
    if (s.device && !byDevice.has(String(s.device))) {
        byDevice.set(String(s.device), s);
    }
}
const missing = [];
const invalid = [];
const discrepancies = [];
for (const id of f.expectedDevices) {
    const s = byDevice.get(id);
    if (!s || !Array.isArray(s.codeWiseProduction) || !s.codeWiseUpdatedAt) {
        missing.push(id);
        continue;
    }
    let sum = 0;
    for (const entry of s.codeWiseProduction) {
        const size = String(entry.tileSize || '').trim().toLowerCase();
        const qty = Number(entry.tileCount);
        if (!size || size === 'unknown' || !Number.isFinite(qty) || qty < 0) {
            invalid.push(`${id}: invalid size/count in codeWiseProduction`);
            break;
        }
        sum += qty;
    }
    const summaryCount = Number(s.tileCount);
    if (Number.isFinite(summaryCount) && Math.abs(sum - summaryCount) > 0.001) {
        discrepancies.push({device:id,summaryTiles:summaryCount,codeWiseTiles:sum,differenceTiles:sum-summaryCount});
    }
}
if (missing.length || invalid.length) {
    node.status({fill:'yellow',shape:'ring',text:`waiting ${f.snapshotId}, missing=${missing.length}, invalid=${invalid.length}`});
    node.warn('Floor stock waiting: missing='+missing.join(', ')+'; invalid='+invalid.join('; '));
    return null;
}
f.discrepancies = discrepancies;
if (discrepancies.length) {
    node.warn('Floor stock shift count discrepancies (using codeWiseProduction): '+JSON.stringify(discrepancies));
}
node.status({fill:discrepancies.length?'yellow':'green',shape:'dot',text:`ready ${f.snapshotId}; mismatches=${discrepancies.length}`});
f.lines = Object.fromEntries(f.expectedDevices.map(id => [id, byDevice.get(id)]));
msg.collection = 'floorStocks';
msg.operation = 'find';
msg.payload = [{}, {sort:{_id:-1},limit:1}];
return msg;

const f=msg.floorStock;
if(!f?.lines) return null;
const previous=(Array.isArray(msg.payload)?msg.payload:[])[0]||null;
if(previous && String(previous._id)>=f.snapshotId) {
 node.status({fill:'blue',shape:'ring',text:`already saved or older: ${f.snapshotId}`});
 return null;
}
const sizes=new Map();
function item(key) {
 if(!sizes.has(key)) sizes.set(key,{tileSize:key,openingStock:0,kilnOutput:0,kedaOutput:0});
 return sizes.get(key);
}
function normalSize(x) {return String(x||'').trim().toLowerCase().replace(/\s+/g,'').replace(/×/g,'x');}
function area(size){const a=size.split('x').map(Number);return a.length===2&&a.every(n=>Number.isFinite(n)&&n>0)?a[0]*a[1]/10000:0;}
for(const old of previous?.stocks||[]) {
 const k=normalSize(old.tileSize);if(!k) continue;
 const x=item(k);x.openingStock=Number(old.closingStock||0);
}
for(const id of f.expectedDevices) {
 const s=f.lines[id];const role=f.roles[id];
 for(const row of s.codeWiseProduction) {
  const k=normalSize(row.tileSize);
  const qty=Number(row.tileCount);
  if(!k || k==='unknown' || !Number.isFinite(qty) || qty<0) {node.error(`Invalid code-wise production for ${id}`,msg);return null;}
  if(role==='kiln') item(k).kilnOutput+=qty;
  else item(k).kedaOutput+=qty;
 }
}
const result=[...sizes.values()].map(s=>{
 const raw=s.openingStock+s.kilnOutput-s.kedaOutput;
 const closing=Math.max(0,raw);
 return {...s,rawClosingStock:raw,closingStock:closing,closingStockM2:Math.round(closing*area(s.tileSize)*100)/100,clampedToZero:raw<0};
}).sort((a,b)=>a.tileSize.localeCompare(b.tileSize));
const from = f.shift==='06-14' ? `${f.shiftDate}T06:00:00+05:30` : f.shift==='14-22' ? `${f.shiftDate}T14:00:00+05:30` : `${f.shiftDate}T22:00:00+05:30`;
const end = Math.max(...f.expectedDevices.map(id=>Date.parse(f.lines[id].shiftEnd||'')));
if(!Number.isFinite(end)) {node.error('Missing shiftEnd from line summaries',msg);return null;}
const doc={_id:f.snapshotId,shiftDate:f.shiftDate,shift:f.shift,
 shiftStart:new Date(from).toISOString(),shiftEnd:new Date(end).toISOString(),
 status:'completed',previousSnapshotId:previous?previous._id:null,
 expectedDevices:f.expectedDevices,productionCountDiscrepancies:f.discrepancies||[],stocks:result,
 totalFloorStockM2:Math.round(result.reduce((n,s)=>n+s.closingStockM2,0)*100)/100,
 calculatedAt:new Date().toISOString()};
msg.floorStockDocument=doc;
msg.collection='floorStocks';msg.operation='insertOne';msg.payload=[doc];
return msg;
